import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

const view = (h) => h.node();

test('starts a follower in term 0', async () => {
  const h = await createHost();
  assert.deepEqual(await view(h), { role: 'follower', term: 0 });
});

test('election path: timeout, win, quorum lost', async () => {
  const h = await createHost();
  assert.deepEqual(await h.electionTimeout(), { ok: true });
  assert.deepEqual(await view(h), { role: 'candidate', term: 1 });
  assert.equal((await h.electionTimeout()).ok, true);
  assert.deepEqual(await view(h), { role: 'candidate', term: 2 });
  assert.equal((await h.electionWon()).ok, true);
  assert.deepEqual(await view(h), { role: 'leader', term: 2 });
  assert.equal((await h.electionTimeout()).ok, false);
  assert.equal((await h.electionWon()).ok, false);
  assert.equal((await h.quorumLost()).ok, true);
  assert.deepEqual(await view(h), { role: 'follower', term: 2 });
  assert.equal((await h.quorumLost()).ok, false);
});

test('electionTimeout refused in term 3', async () => {
  const h = await createHost();
  assert.equal((await h.newerTermSeen(3)).ok, true);
  const r = await h.electionTimeout();
  assert.equal(r.ok, false);
  assert.equal(typeof r.reason, 'string');
  assert.deepEqual(await view(h), { role: 'follower', term: 3 });
});

test('electionWon refused for a follower', async () => {
  const h = await createHost();
  assert.equal((await h.electionWon()).ok, false);
  assert.deepEqual(await view(h), { role: 'follower', term: 0 });
});

test('newerTermSeen', async () => {
  const h = await createHost();
  for (const t of [0, 4, -1, 1.5, NaN, '2']) assert.equal((await h.newerTermSeen(t)).ok, false);
  await h.electionTimeout();
  await h.electionWon(); // leader term 1
  assert.equal((await h.newerTermSeen(1)).ok, false);
  assert.equal((await h.newerTermSeen(2)).ok, true);
  assert.deepEqual(await view(h), { role: 'follower', term: 2 });
});

test('shutdown is final and keeps the term', async () => {
  const h = await createHost();
  await h.electionTimeout();
  assert.equal((await h.shutdown()).ok, true);
  assert.deepEqual(await view(h), { role: 'shutdown', term: 1 });
  for (const r of [await h.electionTimeout(), await h.electionWon(), await h.newerTermSeen(3), await h.quorumLost(), await h.shutdown()]) {
    assert.equal(r.ok, false);
  }
  assert.deepEqual(await view(h), { role: 'shutdown', term: 1 });
});

test('fresh systems are independent', async () => {
  const a = await createHost();
  await a.shutdown();
  const b = await createHost();
  assert.deepEqual(await view(b), { role: 'follower', term: 0 });
});

