import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

const view = (h) => h.node();
const v = (role, term, votedFor) => ({ role, term, votedFor });

test('starts a follower in term 0 that has not voted', async () => {
  const h = await createHost();
  assert.deepEqual(await view(h), v('follower', 0, 'nobody'));
});

test('election path: timeout, win, quorum lost', async () => {
  const h = await createHost();
  assert.deepEqual(await h.electionTimeout(), { ok: true });
  assert.deepEqual(await view(h), v('candidate', 1, 'itself'));
  assert.equal((await h.electionTimeout()).ok, true);
  assert.deepEqual(await view(h), v('candidate', 2, 'itself'));
  assert.equal((await h.electionWon()).ok, true);
  assert.deepEqual(await view(h), v('leader', 2, 'itself'));
  assert.equal((await h.electionTimeout()).ok, false);
  assert.equal((await h.electionWon()).ok, false);
  assert.equal((await h.quorumLost()).ok, true);
  assert.deepEqual(await view(h), v('follower', 2, 'itself'));
  assert.equal((await h.quorumLost()).ok, false);
});

test('electionTimeout refused in term 3', async () => {
  const h = await createHost();
  assert.equal((await h.newerTermSeen(3)).ok, true);
  const r = await h.electionTimeout();
  assert.equal(r.ok, false);
  assert.equal(typeof r.reason, 'string');
  assert.deepEqual(await view(h), v('follower', 3, 'nobody'));
});

test('electionWon refused for a follower', async () => {
  const h = await createHost();
  assert.equal((await h.electionWon()).ok, false);
  assert.deepEqual(await view(h), v('follower', 0, 'nobody'));
});

test('newerTermSeen', async () => {
  const h = await createHost();
  for (const t of [0, 4, -1, 1.5, NaN, '2']) assert.equal((await h.newerTermSeen(t)).ok, false);
  await h.electionTimeout();
  await h.electionWon(); // leader term 1
  assert.equal((await h.newerTermSeen(1)).ok, false);
  assert.equal((await h.newerTermSeen(2)).ok, true);
  assert.deepEqual(await view(h), v('follower', 2, 'nobody'));
});

test('shutdown is final and keeps the term', async () => {
  const h = await createHost();
  await h.electionTimeout();
  assert.equal((await h.shutdown()).ok, true);
  assert.deepEqual(await view(h), v('shutdown', 1, 'itself'));
  for (const r of [await h.electionTimeout(), await h.electionWon(), await h.newerTermSeen(3), await h.quorumLost(), await h.shutdown(), await h.voteRequested('n1', 3)]) {
    assert.equal(r.ok, false);
  }
  assert.deepEqual(await view(h), v('shutdown', 1, 'itself'));
});

test('fresh systems are independent', async () => {
  const a = await createHost();
  await a.shutdown();
  const b = await createHost();
  assert.deepEqual(await view(b), v('follower', 0, 'nobody'));
});

test('vote request validation', async () => {
  const h = await createHost();
  for (const [c, t] of [['n3', 1], ['itself', 1], ['nobody', 1], ['n1', 0], ['n1', 4], ['n1', 1.5], ['n1', '1']]) {
    const r = await h.voteRequested(c, t);
    assert.equal(r.ok, false, `${c} ${t}`);
    assert.equal(typeof r.reason, 'string');
  }
  assert.deepEqual(await view(h), v('follower', 0, 'nobody'));
});

test('newer term vote: becomes follower and grants', async () => {
  const h = await createHost();
  await h.electionTimeout();
  await h.electionWon(); // leader 1
  assert.deepEqual(await h.voteRequested('n2', 2), { ok: true });
  assert.deepEqual(await view(h), v('follower', 2, 'n2'));
});

test('same term: votes at most once, repeat for same candidate ok', async () => {
