const validTerm = (t) => Number.isInteger(t) && t >= 1 && t <= 3;

export const stateInvariants = [
  { name: 'role-is-known', pred: (s) => ROLES.includes(s.role) },
  { name: 'vote-is-known', pred: (s) => VOTES.includes(s.votedFor) },
  { name: 'term-in-0..3', pred: (s) => Number.isInteger(s.term) && s.term >= 0 && s.term <= 3 },
  // Every non-zero term was reached by an election or a newer term; a leader in term 0 is impossible.
  { name: 'no-leader-in-term-0', pred: (s) => !(s.role === 'leader' && s.term === 0) },
  // No vote can be cast in term 0 (requests are for terms 1 to 3, elections move to term 1+).
  { name: 'no-vote-in-term-0', pred: (s) => s.term !== 0 || s.votedFor === 'nobody' },
  // A candidate or leader started an election in its term and voted for itself, so it voted for nobody else.
  { name: 'candidate-and-leader-voted-for-themselves', pred: (s) => !(s.role === 'candidate' || s.role === 'leader') || s.votedFor === 'itself' },
];

const changed = (pre, post) => pre.role !== post.role || pre.term !== post.term || pre.votedFor !== post.votedFor;

