import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
import { loadSpec } from '../tools/polygraph/scripts/load-spec.mjs';
import { step } from '../src/core.ts';

const require = createRequire(import.meta.url);
const { makeSamAdapter } = require('../tools/polygraph/scripts/sam-adapter.cjs');

test('spec matches core on every state and command', () => {
  const adapter = makeSamAdapter(loadSpec(new URL('../spec/node.spec.cjs', import.meta.url).pathname.replace(/^\/(\w:)/, '$1')));
  const roles = ['follower', 'candidate', 'leader', 'shutdown'];
  const votes = ['nobody', 'itself', 'n1', 'n2'];
  const terms = [-1, 0, 1, 2, 3, 4, 1.5];
  const cmds = [
    ['electionTimeout', {}], ['electionWon', {}], ['quorumLost', {}], ['shutdown', {}],
    ...terms.map((term) => ['newerTermSeen', { term }]),
    ...['n1', 'n2', 'n3', 'itself'].flatMap((candidate) => terms.map((term) => ['voteRequested', { candidate, term }])),
  ];
  let n = 0;
  for (const role of roles) for (let term = 0; term <= 3; term++) for (const votedFor of votes) for (const [type, data] of cmds) {
    const pre = { role, term, votedFor };
    const code = step(pre, { type, ...data });
    const spec = adapter.step(pre, type, data);
    const where = JSON.stringify({ pre, type, data });
    if (code.ok) {
      assert.equal(spec.verdict, 'accepted', where);
      assert.deepEqual(spec.state, code.state, where);
    } else {
      assert.equal(spec.verdict, 'rejected', where);
      assert.equal(spec.reason, code.reason, where);
    }
    n++;
  }
  assert.equal(n, 64 * cmds.length);
});

