import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

const view = (h) => h.node();
const v = (role, term, votedFor) => ({ role, term, votedFor });

test('starts a follower in term 0 that has not voted', async () => {
  const h = await createHost();
  assert.deepEqual(await view(h), v('follower', 0, 'nobody'));
});

test('election path: timeout, win, quorum lost', async () => {
  const h = await createHost();
  assert.deepEqual(await h.electionTimeout(), { ok: true });
  assert.deepEqual(await view(h), v('candidate', 1, 'itself'));
  assert.equal((await h.electionTimeout()).ok, true);
  assert.deepEqual(await view(h), v('candidate', 2, 'itself'));
  assert.equal((await h.electionWon()).ok, true);
  assert.deepEqual(await view(h), v('leader', 2, 'itself'));
  assert.equal((await h.electionTimeout()).ok, false);
  assert.equal((await h.electionWon()).ok, false);
  assert.equal((await h.quorumLost()).ok, true);
  assert.deepEqual(await view(h), v('follower', 2, 'itself'));
  assert.equal((await h.quorumLost()).ok, false);
});

test('electionTimeout refused in term 3', async () => {
  const h = await createHost();
  assert.equal((await h.newerTermSeen(3)).ok, true);
  const r = await h.electionTimeout();
  assert.equal(r.ok, false);
  assert.equal(typeof r.reason, 'string');
  assert.deepEqual(await view(h), v('follower', 3, 'nobody'));
});

test('electionWon refused for a follower', async () => {
  const h = await createHost();
  assert.equal((await h.electionWon()).ok, false);
  assert.deepEqual(await view(h), v('follower', 0, 'nobody'));
});

test('newerTermSeen', async () => {
  const h = await createHost();
