'use strict';
// SAM v2 strict-profile specification of src/core.ts `step` (a consensus node's role, term and vote).

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const MAX_TERM = 3;
const PEERS = ['n1', 'n2'];
// role: 'follower' | 'candidate' | 'leader' | 'shutdown'; votedFor: 'nobody' | 'itself' | 'n1' | 'n2'
const INITIAL_STATE = { role: 'follower', term: 0, votedFor: 'nobody' };

const validTerm = (t) => typeof t === 'number' && Number.isInteger(t) && t >= 1 && t <= MAX_TERM;

const noData = () => ({ action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] });
const TERMS = [-1, 0, 1, 2, 3, 4, 1.5];

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      role: { type: 'string' },
      term: { type: 'number' },
      votedFor: { type: 'string' },
    },
    actions: {
      electionTimeout: noData(),
      electionWon: noData(),
      electionLost: noData(),
      newerTermSeen: {
        action: (data = {}) => ({ ...data }),
        schema: {},
        domain: TERMS.map((term) => ({ term })),
      },
      quorumLost: noData(),
      shutdown: noData(),
      voteRequested: {
        action: (data = {}) => ({ ...data }),
        schema: {},
        domain: ['n1', 'n2', 'n3', 'itself', 'nobody'].flatMap((candidate) => TERMS.map((term) => ({ candidate, term }))),
      },
    },
    acceptors: {
      electionTimeout: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('node is shut down');
        if (model.role === 'leader') return reject('the leader does not time out');
        if (model.term >= MAX_TERM) return reject('no term after 3');
        next.role = 'candidate';
        next.term = model.term + 1;
        next.votedFor = 'itself';
      },
      electionWon: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('node is shut down');
        if (model.role !== 'candidate') return reject('only a candidate can win an election');
        next.role = 'leader';
        unchanged('term', 'votedFor');
      },
      electionLost: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('node is shut down');
        if (model.role !== 'candidate') return reject('only a candidate can lose an election');
        next.role = 'follower';
        unchanged('term', 'votedFor');
      },
      newerTermSeen: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('node is shut down');
        const t = proposal.term;
        if (!validTerm(t)) return reject('term must be an integer from 1 to 3');
        if (t <= model.term) return reject('term is not newer');
        next.role = 'follower';
        next.term = t;
        next.votedFor = 'nobody';
      },
      quorumLost: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('node is shut down');
        if (model.role !== 'leader') return reject('only the leader can lose quorum');
        next.role = 'follower';
        unchanged('term', 'votedFor');
      },
      shutdown: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('node is shut down');
        next.role = 'shutdown';
        unchanged('term', 'votedFor');
      },
      voteRequested: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('node is shut down');
        const { candidate, term: t } = proposal;
        if (!PEERS.includes(candidate)) return reject('unknown candidate');
        if (!validTerm(t)) return reject('term must be an integer from 1 to 3');
        if (t > model.term) {
          next.role = 'follower';
          next.term = t;
          next.votedFor = candidate;
          return;
        }
        if (t < model.term) return reject('vote request from an older term');
        if (model.role !== 'follower') return reject('only a follower grants its vote in its own term');
        if (model.votedFor !== 'nobody' && model.votedFor !== candidate) return reject('already voted in this term');
        next.votedFor = candidate;
        unchanged('role', 'term');
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  electionTimeout: (data = {}) => intents.electionTimeout(data),
  electionWon: (data = {}) => intents.electionWon(data),
  electionLost: (data = {}) => intents.electionLost(data),
  newerTermSeen: (data = {}) => intents.newerTermSeen(data),
  quorumLost: (data = {}) => intents.quorumLost(data),
  shutdown: (data = {}) => intents.shutdown(data),
  voteRequested: (data = {}) => intents.voteRequested(data),
};

module.exports = { instance, init, actions, getState, setState };

