// The rules the brief requires, stated over { role, term, votedFor }.
const ROLES = ['follower', 'candidate', 'leader', 'shutdown'];
const VOTES = ['nobody', 'itself', 'n1', 'n2'];
const PEERS = ['n1', 'n2'];
const validTerm = (t) => Number.isInteger(t) && t >= 1 && t <= 3;

export const stateInvariants = [
  { name: 'role-is-known', pred: (s) => ROLES.includes(s.role) },
  { name: 'vote-is-known', pred: (s) => VOTES.includes(s.votedFor) },
  { name: 'term-in-0..3', pred: (s) => Number.isInteger(s.term) && s.term >= 0 && s.term <= 3 },
  // Every non-zero term was reached by an election or a newer term; a leader in term 0 is impossible.
  { name: 'no-leader-in-term-0', pred: (s) => !(s.role === 'leader' && s.term === 0) },
  // No vote can be cast in term 0 (requests are for terms 1 to 3, elections move to term 1+).
  { name: 'no-vote-in-term-0', pred: (s) => s.term !== 0 || s.votedFor === 'nobody' },
  // A candidate or leader started an election in its term and voted for itself, so it voted for nobody else.
  { name: 'candidate-and-leader-voted-for-themselves', pred: (s) => !(s.role === 'candidate' || s.role === 'leader') || s.votedFor === 'itself' },
];

const changed = (pre, post) => pre.role !== post.role || pre.term !== post.term || pre.votedFor !== post.votedFor;

export const transitionInvariants = [
  { name: 'term-never-goes-down', pred: (pre, a, d, post) => post.term >= pre.term },
  {
    name: 'only-election-or-newer-term-changes-term',
    pred: (pre, a, d, post) =>
      post.term === pre.term
      || (a === 'electionTimeout' && post.term === pre.term + 1 && post.role === 'candidate')
      || ((a === 'newerTermSeen' || a === 'voteRequested') && post.term === d.term && d.term > pre.term && post.role === 'follower'),
  },
  {
    name: 'vote-on-entering-a-term',
    pred: (pre, a, d, post) =>
      post.term === pre.term
      || (a === 'electionTimeout' && post.votedFor === 'itself')
      || (a === 'newerTermSeen' && post.votedFor === 'nobody')
      || (a === 'voteRequested' && post.votedFor === d.candidate),
  },
  {
    name: 'votes-at-most-once-in-a-term',
    pred: (pre, a, d, post) => post.term !== pre.term || pre.votedFor === 'nobody' || post.votedFor === pre.votedFor,
  },
  {
    name: 'vote-changes-only-by-vote-or-term-change',
    pred: (pre, a, d, post) => pre.votedFor === post.votedFor || pre.term !== post.term || a === 'voteRequested',
  },
  {
    name: 'leader-was-candidate-first-in-its-term',
    pred: (pre, a, d, post) =>
      post.role !== 'leader' || pre.role === 'leader'
      || (pre.role === 'candidate' && pre.term === post.term && a === 'electionWon'),
  },
  {
    name: 'leader-stays-leader-only-unchanged',
    pred: (pre, a, d, post) => !(pre.role === 'leader' && post.role === 'leader') || !changed(pre, post),
  },
  { name: 'shutdown-stays-shutdown', pred: (pre, a, d, post) => pre.role !== 'shutdown' || !changed(pre, post) },
  {
    name: 'shutdown-keeps-term-and-vote',
    pred: (pre, a, d, post) => a !== 'shutdown' || (post.term === pre.term && post.votedFor === pre.votedFor),
  },
  {
    name: 'candidate-only-from-timeout',
    pred: (pre, a, d, post) => post.role !== 'candidate' || (pre.role === 'candidate' && !changed(pre, post)) || a === 'electionTimeout',
  },
  {
    name: 'follower-change-requires-newer-term-quorum-loss-or-vote',
    pred: (pre, a, d, post) => !changed(pre, post) || post.role !== 'follower' || ['newerTermSeen', 'quorumLost', 'voteRequested', 'electionLost'].includes(a),
  },
  {
    name: 'lost-election-keeps-term-and-self-vote',
    pred: (pre, a, d, post) => a !== 'electionLost' || !changed(pre, post)
      || (pre.role === 'candidate' && post.role === 'follower' && post.term === pre.term && post.votedFor === 'itself'),
  },
];

// Obligations about refusals: v = { rejected, reason } for each explored step.
const accepted = (v) => !(v && v.rejected);
export const rejectionInvariants = [
  { name: 'shutdown-refuses-everything', pred: (s, a, d, v) => s.role !== 'shutdown' || !accepted(v) },
  { name: 'leader-refuses-timeout', pred: (s, a, d, v) => !(a === 'electionTimeout' && s.role === 'leader') || !accepted(v) },
  { name: 'term-3-refuses-timeout', pred: (s, a, d, v) => !(a === 'electionTimeout' && s.term === 3) || !accepted(v) },
  { name: 'won-only-by-candidate', pred: (s, a, d, v) => !(a === 'electionWon' && s.role !== 'candidate') || !accepted(v) },
  { name: 'lost-accepted-exactly-for-candidate', pred: (s, a, d, v) => a !== 'electionLost' || accepted(v) === (s.role === 'candidate') },
  { name: 'quorum-lost-only-by-leader', pred: (s, a, d, v) => !(a === 'quorumLost' && s.role !== 'leader') || !accepted(v) },
  {
    name: 'newer-term-must-be-1..3-and-newer',
    pred: (s, a, d, v) =>
      a !== 'newerTermSeen' || accepted(v) === (s.role !== 'shutdown' && validTerm(d.term) && d.term > s.term),
  },
  {
    name: 'timeout-accepted-when-allowed',
    pred: (s, a, d, v) => a !== 'electionTimeout' || accepted(v) === ((s.role === 'follower' || s.role === 'candidate') && s.term < 3),
  },
  { name: 'shutdown-accepted-when-live', pred: (s, a, d, v) => a !== 'shutdown' || accepted(v) === (s.role !== 'shutdown') },
  {
    name: 'vote-granted-exactly-when-allowed',
    pred: (s, a, d, v) =>
      a !== 'voteRequested' || accepted(v) === (
        s.role !== 'shutdown' && PEERS.includes(d.candidate) && validTerm(d.term) && (
          d.term > s.term
          || (d.term === s.term && s.role === 'follower' && (s.votedFor === 'nobody' || s.votedFor === d.candidate))
        )
      ),
  },
];

