1	// The polygraph spec and src/core.ts must agree on every (state, command): same verdict, reason and post-state.
2	import { test } from 'node:test';
3	import assert from 'node:assert/strict';
4	import { createRequire } from 'node:module';
5	import { loadSpec } from '../tools/polygraph/scripts/load-spec.mjs';
6	import { step } from '../src/core.ts';
7	
8	const require = createRequire(import.meta.url);
9	const { makeSamAdapter } = require('../tools/polygraph/scripts/sam-adapter.cjs');
10	
11	test('spec matches core on every state and command', () => {
12	  const adapter = makeSamAdapter(loadSpec(new URL('../spec/node.spec.cjs', import.meta.url).pathname.replace(/^\/(\w:)/, '$1')));
13	  const roles = ['follower', 'candidate', 'leader', 'shutdown'];
14	  const votes = ['nobody', 'itself', 'n1', 'n2'];
15	  const terms = [-1, 0, 1, 2, 3, 4, 1.5];
16	  const cmds = [
17	    ['electionTimeout', {}], ['electionWon', {}], ['electionLost', {}], ['quorumLost', {}], ['shutdown', {}],
18	    ...terms.map((term) => ['newerTermSeen', { term }]),
19	    ...['n1', 'n2', 'n3', 'itself'].flatMap((candidate) => terms.map((term) => ['voteRequested', { candidate, term }])),
20	  ];
21	  let n = 0;
22	  for (const role of roles) for (let term = 0; term <= 3; term++) for (const votedFor of votes) for (const [type, data] of cmds) {
23	    const pre = { role, term, votedFor };
24	    const code = step(pre, { type, ...data });
25	    const spec = adapter.step(pre, type, data);
26	    const where = JSON.stringify({ pre, type, data });
27	    if (code.ok) {
28	      assert.equal(spec.verdict, 'accepted', where);
29	      assert.deepEqual(spec.state, code.state, where);
30	    } else {
31	      assert.equal(spec.verdict, 'rejected', where);
32	      assert.equal(spec.reason, code.reason, where);
33	    }
34	    n++;
35	  }
36	  assert.equal(n, 64 * cmds.length);
37	});
38

