const v = (role, term, votedFor, paused = false) => ({ role, term, votedFor, paused });

test('pause and resume', async () => {
  const h = await createHost();
  assert.equal((await h.resume()).ok, false);
  assert.deepEqual(await h.pause(), { ok: true });
  assert.deepEqual(await view(h), v('follower', 0, 'nobody', true));
  assert.equal((await h.pause()).ok, false);
  assert.equal((await h.electionTimeout()).ok, false);
  assert.deepEqual(await view(h), v('follower', 0, 'nobody', true));
  assert.equal((await h.newerTermSeen(1)).ok, true);
  assert.deepEqual(await view(h), v('follower', 1, 'nobody', true));
  assert.equal((await h.voteRequested('n1', 1)).ok, true);
  assert.equal((await h.voteRequested('n2', 2)).ok, true);
  assert.deepEqual(await view(h), v('follower', 2, 'n2', true));
  assert.deepEqual(await h.resume(), { ok: true });
  assert.deepEqual(await view(h), v('follower', 2, 'n2', false));
  assert.equal((await h.resume()).ok, false);
  assert.equal((await h.electionTimeout()).ok, true);
  assert.deepEqual(await view(h), v('candidate', 3, 'itself'));
  assert.equal((await h.pause()).ok, false); // candidate
  await h.electionWon();
  assert.equal((await h.pause()).ok, false); // leader
  await h.quorumLost();
  assert.equal((await h.pause()).ok, true); // stepped-down leader is a follower
  assert.deepEqual(await view(h), v('follower', 3, 'itself', true));
});

test('a paused node that shuts down stays shut down', async () => {
  const h = await createHost();
  await h.pause();
  assert.equal((await h.shutdown()).ok, true);
  assert.equal((await h.resume()).ok, false);
  assert.equal((await h.pause()).ok, false);
  assert.equal((await view(h)).role, 'shutdown');
});

